"""
logo_data.py
Almacena el logo oficial de KrediYA en Base64 para acceso universal
tanto en entornos locales (Desktop/Streamlit) como Serverless (Vercel).
"""

import os
import io
import base64
from PIL import Image

KREDIYA_LOGO_B64 = ""
KREDIYA_LOGO_DATA_URI = "data:image/png;base64," + KREDIYA_LOGO_B64

def get_krediya_logo_bytes():
    return base64.b64decode(KREDIYA_LOGO_B64)

def get_krediya_logo_pil():
    return Image.open(io.BytesIO(get_krediya_logo_bytes()))
